-- Writes the generated files from a plan (gen/init.lua): service.lua (shapes, errors and
-- operations as data), init.lua (the client class), README.md. types.lua is
-- gen/types.lua's.
local compat = require("distilled.compat")
local emit = require("distilled.gen.emit")
local naming = require("distilled.gen.naming")
local gen_errors = require("distilled.gen.errors")

local writer = {}

--- writer.header(plan, what) -> comment lines naming the model hash, never a time
function writer.header(plan, what)
  local m, spec = plan.model, plan.provider
  local source = (m.path and string.match(m.path, "([^/]+)$")) or "model"
  local lines = {
    "-- " .. what,
    "--",
    "-- Generated by distilled-lua (generator "
      .. plan.generator_version
      .. ") from "
      .. source
      .. " ("
      .. m.hash
      .. ", "
      .. m.bytes
      .. " bytes)",
    "-- with provider spec " .. spec.name .. ". Do not edit: regenerate with bin/distilled-lua.",
  }
  local count = #plan.ops
  local total = #m.operations
  if plan.selected_all then
    lines[#lines + 1] = "-- Operations: all " .. total .. "."
  else
    lines[#lines + 1] = "-- Operations: " .. count .. " of " .. total .. " (--ops)."
  end
  if not plan.telemetry then
    lines[#lines + 1] = "-- Telemetry: off (--no-telemetry)."
  end
  return lines
end

---------------------------------------------------------------------------------------
-- service.lua
---------------------------------------------------------------------------------------

--- writer.service(plan) -> { ["service.lua"] = source }
function writer.service(plan)
  local b = emit.buffer()
  b:lines_of(
    writer.header(
      plan,
      plan.provider.title .. " service descriptor: shapes, errors and operations as data."
    )
  )
  b:line("--")
  b:lines_of(
    emit.comment(
      "Contract: docs/interfaces.md, 'Schema nodes' and 'Operation and service descriptors'. "
        .. "Shapes are registry entries referenced by name (S.ref), so recursive shapes need "
        .. "nothing special."
    )
  )
  b:line('local S = require("distilled.schema")')
  b:line('local errors = require("distilled.errors")')
  if plan.ctx.uses_json then
    b:line('local json = require("distilled.json")')
  end
  b:blank()
  b:line("local shapes = {}")
  b:blank()
  for _, n in ipairs(plan.nodes) do
    local target = "shapes"
      .. (naming.is_identifier(n.name) and ("." .. n.name) or ("[" .. emit.string(n.name) .. "]"))
    b:lines_of(emit.assign(target, n.node))
  end
  b:blank()
  b:line("local classes = {}")
  b:blank()
  for _, d in ipairs(plan.errors) do
    local target = "classes"
      .. (naming.is_identifier(d.tag) and ("." .. d.tag) or ("[" .. emit.string(d.tag) .. "]"))
    b:lines_of(emit.value(gen_errors.value(d), "", target .. " = errors.define(", ")"))
  end
  b:blank()
  b:line("local ops = {}")
  b:blank()
  local ops_mod = require("distilled.gen.ops")
  for _, op in ipairs(plan.ops) do
    b:lines_of(emit.assign("ops." .. op.method_name, ops_mod.descriptor(plan.ctx, op)))
  end
  b:blank()
  local svc = {
    name = plan.provider.name,
    shapes = emit.raw("shapes"),
    errors = emit.raw("classes"),
    ops = emit.raw("ops"),
    telemetry = plan.service_telemetry,
  }
  -- expanded on purpose (one key per line), whatever its width
  b:line("return {")
  for _, k in ipairs({ "name", "shapes", "errors", "ops", "telemetry" }) do
    if svc[k] ~= nil then
      b:lines_of(emit.value(svc[k], "  ", emit.key(k), ","))
    end
  end
  b:line("}")
  return { ["service.lua"] = b:text() }
end

---------------------------------------------------------------------------------------
-- init.lua (the client class)
---------------------------------------------------------------------------------------

--- writer.client(plan) -> source of init.lua
function writer.client(plan)
  local spec = plan.provider
  local b = emit.buffer()
  b:lines_of(
    writer.header(plan, spec.title .. ' client: what require("' .. spec.name .. '") returns.')
  )
  b:line("--")
  b:lines_of(emit.comment("local " .. spec.title .. ' = require("' .. spec.name .. '")'))
  b:lines_of(emit.comment("local client = " .. spec.title .. ".new({ transport = ... })"))
  b:lines_of(emit.comment("See README.md next to this file for the options and operations."))
  b:line('local Client = require("distilled.client")')
  if not spec.protocol then
    b:line('local rest = require("distilled.protocol.rest")')
  end
  b:blank()
  b:lines_of(
    emit.comment(
      "The module's own name, so the client loads under whatever directory it was vendored as."
    )
  )
  b:line("local MODULE = ... or " .. emit.string(spec.name))
  b:line('local service = require(MODULE .. ".service")')
  b:blank()

  -- options
  local options = {}
  local auth = spec.auth
  if auth.kind ~= "none" then
    options[auth.from] = { secret = true, env = auth.env, required = true }
  end
  options[spec.base_url.option] = { default = spec.base_url.default, env = spec.base_url.env }

  local protocol_args = {
    base_url = emit.raw("function(creds)\n    return creds." .. spec.base_url.option .. "\n  end"),
    unknown_tag = spec.unknown_tag,
    parse_tag = spec.parse_tag,
    error_fields_at = spec.error_fields_at,
  }
  if auth.kind == "bearer" then
    protocol_args.headers = emit.call("rest.bearer", auth.from)
  elseif auth.kind == "header" then
    protocol_args.headers = emit.call("rest.header", auth.header, auth.from)
  end
  if spec.classify_error then
    protocol_args.classify_error = emit.call("require", spec.classify_error)
  end

  if spec.error_envelope or spec.status_map then
    b:line('local errors = require("distilled.errors")')
    b:blank()
  end
  if spec.status_map then
    -- rest.new takes the whole map: the built-in one with the provider's entries over it
    b:lines_of(emit.comment("errors.STATUS_MAP with the provider spec's status_map over it."))
    b:line("local status_map = {}")
    b:line("for status, class in pairs(errors.STATUS_MAP) do")
    b:line("  status_map[status] = class")
    b:line("end")
    local statuses = {}
    for k in pairs(spec.status_map) do
      statuses[#statuses + 1] = k
    end
    table.sort(statuses)
    for _, status in ipairs(statuses) do
      local tag = spec.status_map[status]
      local where = plan.error_tags_set[tag] and "service.errors" or "errors.classes"
      b:line("status_map[" .. status .. "] = " .. where .. "." .. tag)
    end
    b:blank()
    protocol_args.status_map = emit.raw("status_map")
  end
  if spec.error_envelope then
    b:lines_of(emit.comment("The provider's error envelope (provider spec error_envelope)."))
    b:line("local function error_envelope(body)")
    b:line("  return {")
    if spec.error_envelope.code then
      b:line("    code = errors.at_pointer(body, " .. emit.string(spec.error_envelope.code) .. "),")
    end
    if spec.error_envelope.message then
      b:line(
        "    message = errors.at_pointer(body, " .. emit.string(spec.error_envelope.message) .. "),"
      )
    end
    b:line("  }")
    b:line("end")
    b:blank()
    protocol_args.error_envelope = emit.raw("error_envelope")
  end

  if spec.protocol then
    b:lines_of(
      emit.comment("Hand-written protocol (provider spec protocol = " .. spec.protocol .. ").")
    )
    b:line("local protocol = require(" .. emit.string(spec.protocol) .. ")(service, {")
    b:line("  unknown_tag = " .. emit.string(spec.unknown_tag) .. ",")
    b:line("  parse_tag = " .. emit.string(spec.parse_tag) .. ",")
    b:line("  base_url_option = " .. emit.string(spec.base_url.option) .. ",")
    b:line("})")
  else
    -- base_url is a function: emitted by hand so it is formatted as stylua would
    b:line("local protocol = rest.new({")
    b:line("  base_url = function(creds)")
    b:line("    return creds." .. spec.base_url.option)
    b:line("  end,")
    protocol_args.base_url = nil
    for _, k in ipairs(emit.sorted_keys(protocol_args)) do
      b:lines_of(emit.value(protocol_args[k], "  ", emit.key(k), ","))
    end
    b:line("})")
  end
  b:blank()
  b:line("return Client.define({")
  b:line("  service = service,")
  b:line("  protocol = protocol,")
  b:lines_of(emit.value(options, "  ", "options = ", ","))
  b:line("})")
  return b:text()
end

---------------------------------------------------------------------------------------
-- README.md
---------------------------------------------------------------------------------------

local function md_escape(s)
  return (string.gsub(s, "|", "\\|"))
end

--- writer.readme(plan) -> markdown
function writer.readme(plan)
  local spec, m = plan.provider, plan.model
  local out = {}
  local function add(s)
    out[#out + 1] = s or ""
  end
  add("# " .. spec.title .. " client (generated)")
  add()
  add("Generated by distilled-lua (generator " .. plan.generator_version .. ") from")
  add("`" .. ((m.path and string.match(m.path, "([^/]+)$")) or "model") .. "` (" .. m.hash .. ")")
  add("with the provider spec `" .. spec.name .. "`. Do not edit; regenerate with")
  add("`bin/distilled-lua generate`. Runtime modules: `bin/distilled-lua vendor --out <dir>`.")
  add()
  local svc_doc = m.service and m.service.traits and m.service.traits["smithy.api#documentation"]
  if svc_doc then
    add(naming.summary(svc_doc))
    add()
  end
  add("## Construct")
  add()
  add("```lua")
  add("-- the directory holding `" .. spec.name .. "/` and `distilled/` on package.path:")
  add('package.path = dir .. "/?.lua;" .. dir .. "/?/init.lua;" .. package.path')
  add()
  add("local " .. spec.title .. ' = require("' .. spec.name .. '")')
  add("local client = " .. spec.title .. ".new({")
  if spec.auth.kind ~= "none" then
    local env = spec.auth.env and (" -- default: $" .. spec.auth.env) or ""
    add("  " .. spec.auth.from .. " = key," .. env)
  end
  add('  transport = require("distilled.transport.popen_curl"),')
  add("})")
  add("```")
  add()
  add("| Option | Meaning |")
  add("| --- | --- |")
  if spec.auth.kind ~= "none" then
    add(
      "| `"
        .. spec.auth.from
        .. "` | required secret: a string, a secret, or `fn(host) -> value, err`"
        .. (spec.auth.env and ("; default from `" .. spec.auth.env .. "`") or "")
        .. " |"
    )
  end
  add(
    "| `"
      .. spec.base_url.option
      .. "` | base URL, default `"
      .. spec.base_url.default
      .. "`"
      .. (spec.base_url.env and ("; or from `" .. spec.base_url.env .. "`") or "")
      .. " |"
  )
  add("| `host`, `transport`, `sleep`, ... | the host seams (see distilled's docs/interfaces.md) |")
  add("| `retry`, `deadline_s`, `tracing`, `validation` | the common client options |")
  add()
  add("Every method returns `value` or `nil, err`; `err.tag` is one of the operation's errors,")
  add(
    "a built-in tag, `"
      .. spec.unknown_tag
      .. "` (nothing matched) or `"
      .. spec.parse_tag
      .. "` (an unparseable body)."
  )
  add()
  add("## Operations (" .. #plan.ops .. ")")
  add()
  add("| Method | HTTP | Summary |")
  add("| --- | --- | --- |")
  for _, op in ipairs(plan.ops) do
    local summary = naming.summary(op.def.traits and op.def.traits["smithy.api#documentation"])
      or ""
    local method = "`" .. op.method_name .. "`"
    if op.pagination then
      method = method .. " (+ `_pages`, `_items`)"
    end
    add(
      "| "
        .. method
        .. " | `"
        .. op.http.method
        .. " "
        .. md_escape(op.http.uri)
        .. "` | "
        .. md_escape(summary)
        .. " |"
    )
  end
  add()
  add("## Errors")
  add()
  add("| Tag | Categories | Matchers |")
  add("| --- | --- | --- |")
  for _, d in ipairs(plan.errors) do
    local cats = compat.concat(d.categories.items, ", ")
    local matchers = d.matchers and emit.inline(d.matchers) or ""
    add("| `" .. d.tag .. "` | " .. cats .. " | `" .. md_escape(matchers) .. "` |")
  end
  add()
  return compat.concat(out, "\n")
end

return writer
